function decode() {
  const bin = typeof atob === 'function' ? atob(B64) : Buffer.from(B64, 'base64').toString('binary');
  const out = [];
  for (let o = 0; o + 162 <= bin.length; o += 162) {
    const vec = new Float32Array(GW * GH);
    for (let i = 0; i < GW * GH; i += 2) { const b = bin.charCodeAt(o + 2 + i / 2); vec[i] = (b >> 4) - 8; vec[i + 1] = (b & 15) - 8; }
    let m = 0; for (const v of vec) m += v; m /= vec.length;
    let s = 0; for (let i = 0; i < vec.length; i++) { vec[i] -= m; s += vec[i] * vec[i]; }
    s = Math.sqrt(s) || 1; for (let i = 0; i < vec.length; i++) vec[i] /= s;
    out.push({ limit: LIM[bin.charCodeAt(o)], asp: bin.charCodeAt(o + 1) / 100, vec });
  }
  return out;
}
export const TEMPLATES = decode();
